package com.flightbooking.ui;

import com.flightbooking.model.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

final class FlightSearchPanel extends JPanel {
    private final AppFrame frame; private final Account account; private final JTable table=Ui.table("Airline","Flight","From","To","Departure","Arrival","Seats left","Economy / Business"); private java.util.List<Flight> current=java.util.List.of();
    private final JButton boardingButton=Ui.button("Your Boarding Pass",false); private final JLabel boardingBadge=new JLabel("0");
    private final JTextField from=Ui.field(14),to=Ui.field(14),date=Ui.field(11),maxPrice=Ui.field(8); private final JCheckBox priceFilter=new JCheckBox("Apply"); private LocalDate selectedDate;
    FlightSearchPanel(AppFrame frame,Account account){this.frame=frame;this.account=account;setLayout(new BorderLayout());setBackground(Ui.PAPER);add(header(),BorderLayout.NORTH);add(content(),BorderLayout.CENTER);reload();}
    private JPanel header(){JPanel bar=new JPanel(new BorderLayout());bar.setBackground(Color.WHITE);bar.setBorder(new EmptyBorder(14,26,14,26));JLabel logo=new JLabel("✈  SKYWARD");logo.setFont(new Font("Segoe UI",Font.BOLD,19));logo.setForeground(Ui.TEAL_DARK);bar.add(logo,BorderLayout.WEST);JPanel right=new JPanel(new FlowLayout(FlowLayout.RIGHT,10,0));right.setOpaque(false);right.add(Ui.muted("Hello, "+account.getName()));JPanel passAction=new JPanel(new FlowLayout(FlowLayout.LEFT,5,0));passAction.setOpaque(false);boardingBadge.setOpaque(true);boardingBadge.setBackground(new Color(220,38,38));boardingBadge.setForeground(Color.WHITE);boardingBadge.setFont(new Font("Segoe UI",Font.BOLD,11));boardingBadge.setBorder(new EmptyBorder(3,7,3,7));boardingBadge.setVisible(false);passAction.add(boardingButton);passAction.add(boardingBadge);right.add(passAction);boardingButton.addActionListener(e->showBoardingPasses());JButton mine=Ui.button("My bookings",false);mine.addActionListener(e->showBookings());right.add(mine);JButton logout=Ui.button("Sign out",false);logout.addActionListener(e->frame.signOut());right.add(logout);bar.add(right,BorderLayout.EAST);refreshBoardingPassBadge();return bar;}
    private JPanel content(){JPanel body=Ui.panel(new BorderLayout(0,18));body.setBorder(new EmptyBorder(26,35,32,35));JPanel hero=new JPanel(new BorderLayout(0,12));hero.setBackground(Ui.DARK);hero.setBorder(new EmptyBorder(25,28,24,28));JPanel words=new JPanel();words.setOpaque(false);words.setLayout(new BoxLayout(words,BoxLayout.Y_AXIS));JLabel title=new JLabel("Go somewhere memorable.");title.setFont(new Font("Segoe UI",Font.BOLD,29));title.setForeground(Color.WHITE);words.add(title);JLabel subtitle=new JLabel("Search available flights and find a fare that fits.");subtitle.setForeground(new Color(209,213,219));subtitle.setFont(Ui.BODY);words.add(Box.createVerticalStrut(5));words.add(subtitle);hero.add(words,BorderLayout.NORTH);
        JPanel search=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));search.setOpaque(false);date.setEditable(false);date.setText("Any date");date.setToolTipText("Choose a departure date");JPanel datePicker=new JPanel(new BorderLayout(4,0));datePicker.setOpaque(false);datePicker.add(date,BorderLayout.CENTER);JButton calendar=Ui.button("▦",false);calendar.setToolTipText("Open calendar");calendar.setMargin(new Insets(5,10,5,10));calendar.addActionListener(e->chooseDate());datePicker.add(calendar,BorderLayout.EAST);maxPrice.setText("4000");maxPrice.setEnabled(false);priceFilter.setOpaque(false);priceFilter.setForeground(Color.WHITE);priceFilter.setToolTipText("Show only flights with an Economy fare at or below the maximum");priceFilter.addActionListener(e->maxPrice.setEnabled(priceFilter.isSelected()));JPanel priceBox=new JPanel(new BorderLayout(5,0));priceBox.setOpaque(false);priceBox.add(priceFilter,BorderLayout.WEST);priceBox.add(maxPrice,BorderLayout.CENTER);JButton find=Ui.button("Search flights",true);find.addActionListener(e->reload());search.add(Ui.formFieldOnDark("Departure date",datePicker));search.add(Ui.formFieldOnDark("From city",from));search.add(Ui.formFieldOnDark("To city",to));search.add(Ui.formFieldOnDark("Max Economy fare (₹)",priceBox));search.add(find);hero.add(search,BorderLayout.SOUTH);body.add(hero,BorderLayout.NORTH);
        JPanel results=new JPanel(new BorderLayout(0,10));results.setOpaque(false);JPanel cap=new JPanel(new BorderLayout());cap.setOpaque(false);cap.add(Ui.title("Available flights"),BorderLayout.WEST);JButton book=Ui.button("Book selected flight",true);book.addActionListener(e->bookSelected());cap.add(book,BorderLayout.EAST);results.add(cap,BorderLayout.NORTH);JScrollPane scroll=new JScrollPane(table);scroll.setBorder(BorderFactory.createLineBorder(Ui.LINE));results.add(scroll,BorderLayout.CENTER);body.add(results,BorderLayout.CENTER);return body;}
    private void chooseDate(){CalendarDialog picker=new CalendarDialog(frame,selectedDate);picker.setVisible(true);selectedDate=picker.getSelectedDate();date.setText(selectedDate==null?"Any date":selectedDate.format(DateTimeFormatter.ofPattern("EEE, d MMM yyyy")));}
    private void reload(){try{java.math.BigDecimal cap=null;if(priceFilter.isSelected()){String value=maxPrice.getText().trim();if(value.isEmpty())throw new IllegalArgumentException("Enter a maximum Economy fare.");cap=new java.math.BigDecimal(value);if(cap.signum()<0)throw new IllegalArgumentException("Maximum fare cannot be negative.");}current=frame.flightDao().search(from.getText(),to.getText(),selectedDate,cap);DefaultTableModel m=Ui.model(table);m.setRowCount(0);DateTimeFormatter fmt=DateTimeFormatter.ofPattern("EEE, d MMM · HH:mm");for(Flight f:current)m.addRow(new Object[]{f.getAirlineName(),f.getFlightNumber(),f.getDepartureCity(),f.getDestinationCity(),fmt.format(f.getDepartureTime()),fmt.format(f.getArrivalTime()),"E "+f.getEconomyAvailableSeats()+" · B "+f.getBusinessAvailableSeats(),"₹"+f.getEconomyPrice()+" · ₹"+f.getBusinessPrice()});if(current.isEmpty())Ui.info(this,"No available flights match. Change the route, date, or maximum fare and search again.");}catch(NumberFormatException ex){Ui.error(this,"Enter a valid maximum fare, such as 4000.");}catch(Exception ex){Ui.error(this,"Could not load flights.\n"+ex.getMessage());}}
    private void bookSelected(){int row=table.getSelectedRow();if(row<0){Ui.info(this,"Select a flight first.");return;}new BookingDialog(frame,account,current.get(table.convertRowIndexToModel(row))).setVisible(true);reload();refreshBoardingPassBadge();}
    private void refreshBoardingPassBadge(){try{int count=frame.bookingDao().boardingPassesForUser(account.getId()).size();boardingBadge.setText(String.valueOf(count));boardingBadge.setVisible(count>0);boardingButton.setToolTipText(count==0?"No confirmed boarding passes yet":count+" confirmed boarding pass"+(count==1?"":"es"));}catch(Exception ex){boardingBadge.setVisible(false);}}
    private void showBoardingPasses(){try{java.util.List<BoardingPass> passes=frame.bookingDao().boardingPassesForUser(account.getId());if(passes.isEmpty()){Ui.info(this,"No confirmed boarding passes yet. Your pass will appear here after a booking is paid and confirmed.");return;}new BoardingPassDialog(frame,account,passes).setVisible(true);refreshBoardingPassBadge();reload();}catch(Exception ex){Ui.error(this,"Could not load your boarding passes.\n"+ex.getMessage());}}
    private void showBookings(){
        try{
            java.util.List<BookingSummary> rows=frame.bookingDao().forUser(account.getId());
            JTable t=Ui.table("Ref","Flight","Route","Departure","Total","Booking","Cancel request");DefaultTableModel m=Ui.model(t);
            DateTimeFormatter fmt=DateTimeFormatter.ofPattern("d MMM yyyy · HH:mm");
            for(BookingSummary b:rows)m.addRow(new Object[]{"SB-"+b.getId(),b.getFlightNumber(),b.getDepartureCity()+" → "+b.getDestinationCity(),fmt.format(b.getDepartureTime()),"₹"+b.getTotal(),b.getStatus(),b.getCancellationStatus()==null?"—":b.getCancellationStatus()});
            JPanel p=new JPanel(new BorderLayout(0,12));p.add(new JScrollPane(t),BorderLayout.CENTER);
            JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));JButton continuePay=Ui.button("Continue payment",true),cancelRequest=Ui.button("Request cancellation",false),refundSummary=Ui.button("View refund summary",false);actions.add(continuePay);actions.add(cancelRequest);actions.add(refundSummary);p.add(actions,BorderLayout.SOUTH);
            JDialog dialog=new JDialog(SwingUtilities.getWindowAncestor(this),"My bookings",Dialog.ModalityType.APPLICATION_MODAL);dialog.setSize(980,430);dialog.setLocationRelativeTo(this);dialog.setContentPane(p);
            continuePay.addActionListener(e->{BookingSummary b=selectedBooking(t,rows,dialog);if(b==null)return;if(!"PENDING".equals(b.getStatus())){Ui.info(dialog,"Only pending bookings can continue to payment.");return;}dialog.dispose();pay(b);});
            cancelRequest.addActionListener(e->{BookingSummary b=selectedBooking(t,rows,dialog);if(b==null)return;if(!"PENDING".equals(b.getStatus())&& !"CONFIRMED".equals(b.getStatus())){Ui.info(dialog,"Only active bookings can be submitted for cancellation.");return;}if("PENDING".equals(b.getCancellationStatus())){Ui.info(dialog,"This request is already waiting for admin approval.");return;}if(JOptionPane.showConfirmDialog(dialog,"Send a cancellation request for booking SB-"+b.getId()+"? The booking and seat remain active until an administrator approves it.","Request cancellation",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{frame.bookingDao().requestCancellation(b.getId(),account.getId());dialog.dispose();Ui.info(this,"Your request was sent. The booking will only be cancelled after admin approval.");showBookings();}catch(Exception ex){Ui.error(dialog,"Could not send the cancellation request.\n"+ex.getMessage());}});
            refundSummary.addActionListener(e->{BookingSummary b=selectedBooking(t,rows,dialog);if(b==null)return;if(!"CANCELLED".equals(b.getStatus())){Ui.info(dialog,"A refund summary is available after the administrator approves cancellation.");return;}try{RefundSummary refund=frame.bookingDao().cancellationRefundForUser(b.getId(),account.getId());new RefundSummaryDialog(dialog,refund).setVisible(true);}catch(Exception ex){Ui.error(dialog,ex.getMessage());}});
            dialog.setVisible(true);
        }catch(Exception ex){Ui.error(this,"Could not load your bookings.\n"+ex.getMessage());}
    }
    private BookingSummary selectedBooking(JTable table,java.util.List<BookingSummary> rows,Component parent){int row=table.getSelectedRow();if(row<0){Ui.info(parent,"Select a booking first.");return null;}return rows.get(table.convertRowIndexToModel(row));}
    private void pay(BookingSummary b){String method=(String)JOptionPane.showInputDialog(this,"Demo checkout. No card or bank details are collected.\nTotal: ₹"+b.getTotal(),"Simulated payment",JOptionPane.QUESTION_MESSAGE,null,new String[]{"CARD","UPI","NET_BANKING"},"CARD");if(method==null)return;try{java.util.List<TicketInfo> tickets=frame.bookingService().pay(b.getId(),account.getId(),method);StringBuilder message=new StringBuilder("Booking confirmed · SB-").append(b.getId()).append("\n\n");for(TicketInfo t:tickets)message.append(t.getPassengerName()).append("   Seat ").append(t.getSeatNumber()).append("   ").append(t.getTicketNumber()).append('\n');Ui.info(this,message.toString());refreshBoardingPassBadge();}catch(Exception ex){Ui.error(this,"Payment could not be completed.\n"+ex.getMessage());}}
}
